const $=s=>document.querySelector(s);
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',weight:'<path d="M2 10v4m3-7v10m3-12v14m0-7h8m0-7v14m3-12v10m3-7v4"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z"/><path d="M7 9h9m-9 4h6"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pin:'<path d="M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',check:'<path d="m5 12 4 4L19 6"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/>',plus:'<path d="M12 5v14M5 12h14"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 8-3 8-3 9h18c0-1-3-1-3-9M10 21h4"/>',shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z"/><path d="m8 12 3 3 5-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v6m-4 2h8"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const p=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return p;};
const names=['김민준','이서연','박지훈','정수빈','최현우'];
const initial={name:'온오프 회원',unit:'lbs',rank:true,noticeOn:true,notice:'온오프와 함께, 오늘의 나를 켜보세요!  ·  수업은 예약 없이 자유롭게 참여할 수 있어요.  ·  운동 후 나의 기록을 남겨주세요.',records:[],attendance:[],rms:[],workouts:{},members:[{id:'demo1',name:'강도윤',status:'pending'},{id:'demo2',name:'윤하린',status:'pending'}],posts:[{id:'p1',category:'운동 번개',title:'토요일 오픈짐, 같이 운동하실 분! 🏋️',body:'토요일 오전 11시에 모여서 함께 운동해요.\n가볍게 팀 운동하고 스트레칭까지!\n참여하실 분은 아래 참여하기 버튼을 눌러주세요.',author:'김민준',date:'2026-10-30',joined:[],comments:[{author:'이서연',text:'같이 해요! 🙌'}]},{id:'p2',category:'공동구매',title:'운동 후 한 잔! 단백질 공동구매',body:'운동 후 함께 마실 단백질 공동구매 수요를 확인합니다.\n참여 의사를 남겨주세요. 구체적인 상품과 가격은 확정 후 안내할게요.\n이 글은 기능 확인을 위한 예시입니다.',author:'ONOFF 코치',date:'2026-10-29',joined:[],comments:[]},{id:'p3',category:'자유글',title:'오늘도 운동 완료! 다들 수고하셨어요',body:'어제보다 조금 더 나아진 오늘.\n함께 운동해서 즐거웠어요!',author:'정수빈',date:'2026-10-29',joined:[],comments:[]}]};
let state;try{state={...structuredClone(initial),...JSON.parse(localStorage.getItem('onoff-v1')||'{}')}}catch{state=structuredClone(initial)}
let page=location.hash.slice(1)||'home',date=today(),program=null,chosenSession=null,coach=false,boardFilter='전체',recordsFilter='WOD',myTab='운동 기록';
const save=()=>{try{localStorage.setItem('onoff-v1',JSON.stringify(state))}catch{toast('저장 공간이 부족해요. 브라우저 저장 공간을 확인해주세요.');throw new Error('Storage unavailable')}};
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const navItems=[['home','home','오늘의 운동'],['members','users','회원 기록'],['records','chart','내 기록'],['rm','weight','내 1RM'],['community','chat','커뮤니티']];
function nav(){let items=[...navItems];if(coach)items.push(['admin','shield','운영 관리']);$('#nav').innerHTML=items.map(([id,ic,title])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(ic)}${title}${id==='community'?'<span class="nav-dot">N</span>':''}</button>`).join('')+'<div class="nav-separator"></div><button data-action="settings">'+icon('settings')+'내 정보</button>';$('#mobile-nav').innerHTML=navItems.map(([id,ic,title])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(ic)}${id==='home'?'홈':title}</button>`).join('');$('#page-label').textContent=page==='admin'?'운영 관리':navItems.find(x=>x[0]===page)?.[2]||'내 정보';document.title=`ONOFF · ${$('#page-label').textContent}`;$('.profile-name').textContent=state.name;$('.profile-button .avatar').textContent=state.name.slice(0,1);$('.coach-mode').innerHTML=coach?'회원 화면으로 돌아가기 <span>↗</span>':'코치 화면 둘러보기 <span>↗</span>';}
function seoulNow(){const f=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date()).split(':');return +f[0]*60+(+f[1]);}
const minutes=s=>s.split(':').reduce((a,v,i)=>a+Number(v)*(i===0?60:1),0);
function schedule(d){const day=new Date(d+'T12:00:00+09:00').getUTCDay();if(day===0)return[];if(day===6)return[{time:'10:00',end:'20:00',type:'OPEN GYM'}];const a=day===2||day===5;let slots=[['09:30',a?'WOD':'B/T'],['11:00',a?'B/T':'WOD'],['12:00','OPEN GYM'],['17:00',a?'WOD':'B/T'],['18:00',a?'B/T':'WOD'],['19:10',a?'WOD':'B/T'],['20:30',a?'B/T':'WOD']];if(day===3)slots=slots.filter(x=>!['17:00','20:30'].includes(x[0])).map(([t,p])=>[t,p==='OPEN GYM'?p:'WOD']);return slots.map(([time,type])=>({time,type,end:type==='OPEN GYM'?'16:30':`${String(Math.floor((minutes(time)+60)/60)).padStart(2,'0')}:${time.split(':')[1]}`}));}
function activeSession(){let d=date;const slots=schedule(d);const now=d===today()?seoulNow():0;let slot=slots.find(s=>minutes(s.time)<=now&&minutes(s.end)>now)||slots.find(s=>minutes(s.time)>now);if(slot)return{...slot,date:d,current:minutes(slot.time)<=now&&now<minutes(slot.end)&&d===today()};for(let i=1;i<=8;i++){const dt=new Date(d+'T12:00:00+09:00');dt.setUTCDate(dt.getUTCDate()+i);const nd=dt.toISOString().slice(0,10);const next=schedule(nd)[0];if(next)return{...next,date:nd,current:false,nextDay:true}}return null;}
function selected(){if(chosenSession)return chosenSession;return activeSession()}
const defaultWorkout=p=>p==='B/T'?{title:'Body Training',sections:[{title:'Find Your Front Squat',text:'Front Squat 1RM 도전!\n충분한 워밍업 후 최고 중량에 도전하세요.',record:true,kind:'1RM',movement:'Front Squat'},{title:'5 Sets · Every 3:30',text:'8 Front Squat (115 / 80 lbs)\n16 Box Step Over (Lateral)\n8 Front Squat',record:true,kind:'중량'}]}:{title:'Work of the Day',sections:[{title:'Snatch Complex · 5 Sets',text:'1 Snatch Lift Off\n1 Snatch Deadlift\n1 Snatch Pull\n1 Squat Snatch',record:true,kind:'중량'},{title:'6 Sets · Every 1:30 / Rest 1:00',text:'ODD\n20 / 18 cal Row\nMax. Power Snatch (135 / 95 lbs)\n\nEVEN\n10 Power Snatch\nMax. Cal Row',record:true,kind:'세트별 횟수·칼로리'}]};
function workout(p=program,d=date){return state.workouts[d+'_'+p]||defaultWorkout(p)}
function formatWeight(lbs){const n=state.unit==='kg'?lbs/2.2046226218:lbs;return Number(n.toFixed(1)).toLocaleString('en-US')}
function workoutText(t){if(state.unit!=='kg')return esc(t);return esc(t.replace(/(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?) lbs/g,(_,a,b)=>`${(+a/2.2046226218).toFixed(1)} / ${(+b/2.2046226218).toFixed(1)} kg`));}
const dateLabel=d=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'long'}).format(new Date(d+'T12:00:00+09:00'));
function datePicker(){return `<div class="date-picker"><button data-action="prev-date" aria-label="이전 날짜">‹</button>${icon('calendar')}<input aria-label="운동 날짜" id="date-input" type="date" value="${date}"><button data-action="next-date" aria-label="다음 날짜">›</button><button data-action="today">오늘</button></div>`}
function intro(title,sub,extra=''){return `<div class="intro"><div><div class="eyebrow">TURN YOURSELF ON.</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function unitToggle(){return `<div class="unit-toggle"><button class="${state.unit==='lbs'?'active':''}" data-unit="lbs">lbs</button><span class="muted">/</span><button class="${state.unit==='kg'?'active':''}" data-unit="kg">kg</button></div>`}
function demoRows(p=program){if(p==='B/T')return names.map((name,i)=>({id:'ex'+i,name,date,program:p,section:'S1',kind:'1RM',lbs:[225,155,205,135,245][i],demo:true,rank:i!==3}));return names.map((name,i)=>({id:'ex'+i,name,date,program:'WOD',section:'S2',kind:'세트별 횟수·칼로리',value:['12 / 21 / 10 / 19 / 8 / 18','9 / 16 / 8 / 15 / 7 / 15','11 / 20 / 10 / 18 / 9 / 17','8 / 14 / 7 / 13 / 6 / 12','14 / 23 / 12 / 21 / 11 / 20'][i],demo:true,rank:i!==3}));}
function resultValue(r){return r.lbs!=null?`${formatWeight(r.lbs)} <small>${state.unit}</small>`:esc(r.value)}
function resultTable(p=program,limit=20){const real=state.records.filter(r=>r.date===date&&r.program===p);const rows=[...real,...demoRows(p)].slice(0,limit);return `<table class="record-table"><thead><tr><th>회원</th><th>구간</th><th>기록</th><th>참여</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="table-name"><span class="avatar">${esc(r.name.slice(0,1))}</span>${esc(r.name)}${r.demo?'':' <span class="tag">내 기록</span>'}</span></td><td><span class="tag">${r.section}</span></td><td><span class="${r.lbs!=null?'record-score':''}" style="${r.lbs==null?'font-size:10px':''}">${resultValue(r)}</span></td><td><span class="mini-badge">${r.rank?'순위 ON':'순위 OFF'}</span>${!r.demo&&coach?` <button class="link" data-edit-record="${r.id}">수정</button>`:''}</td></tr>`).join('')}</tbody></table>`}
function home(){const s=selected();const p=program||((s?.type==='B/T')?'B/T':'WOD');program=p;const wd=workout(p,s?.date||date);const day=s?.date||date;const isOpen=s?.type==='OPEN GYM';const slots=schedule(date);const upcomingLabel=chosenSession?'선택한 수업':s?.nextDay?'다음 운영일':s?.current?'지금 진행 중':'다가오는 수업';const desc=s?.current?'수업이 진행 중이에요':s?.nextDay?dateLabel(day):date===today()?`${Math.max(0,minutes(s.time)-seoulNow())}분 후 시작`:'선택한 날짜의 수업';const attend=state.attendance.filter(d=>d.startsWith(today().slice(0,7))).length;return `${intro('오늘도, 나를 켜는 시간.',`${dateLabel(date)} · 함께 움직이고, 어제보다 한 걸음 더.`,datePicker())}${state.noticeOn?`<div class="notice"><span>${icon('bell')} NOTICE</span><div class="notice-track"><span class="notice-text">${esc(state.notice)}</span></div><button data-action="notice" aria-label="공지 자세히 보기">↗</button></div>`:''}<div class="dashboard"><section class="panel workout-panel"><div class="workout-hero"><div class="hero-top"><div class="status-pill"><i></i>${upcomingLabel}</div><span>${desc}</span></div><div class="hero-title"><div><div class="time">${s?.time||'—'} <span style="font-size:23px;color:#8db4ee">— ${s?.end||'—'}</span></div><p>${isOpen?'나만의 페이스로, 자유롭게 운동하세요.':s?.type==='WOD'?'Work of the Day':'Body Training'}</p></div><div class="hero-type">${isOpen?'OPEN':s?.type||p}</div></div><div class="hero-bottom">${icon('pin')} ONOFF CROSSFIT · ILGWANG <span style="margin-left:auto">${isOpen?'FREE TRAINING':'60 MIN TRAINING'}</span></div></div><div class="workout-tabs"><div class="segmented">${['WOD','B/T'].map(t=>`<button data-program="${t}" class="${p===t?'active':''}">${t}</button>`).join('')}</div><div style="display:flex;align-items:center;gap:12px">${state.workouts[day+'_'+p]?'':'<span class="mini-badge">예시 운동</span>'}${unitToggle()}</div></div><div class="workout-body">${wd.sections.map((sec,i)=>`<div class="workout-section"><div class="section-mark">S${i+1}</div><div><div class="section-heading"><h3>${esc(sec.title)}</h3>${sec.record?`<span class="mini-badge">${esc(sec.kind)} 기록</span>`:''}</div><div class="exercise">${workoutText(sec.text)}</div>${sec.record?`<p class="exercise-note">${icon('edit')} ${sec.kind==='1RM'?'기록하면 내 1RM에 함께 저장돼요.':'운동을 마치고 기록을 남겨주세요.'}</p>`:''}</div></div>`).join('')}</div><div class="workout-actions"><button class="btn soft" data-action="attendance">${icon(state.attendance.includes(today())?'check':'pin')}${state.attendance.includes(today())?'오늘 출석 완료':'출석하기'}</button><button class="btn primary" data-action="record">${icon('edit')}기록 입력</button></div></section><div class="right-column"><section class="panel"><div class="panel-head"><h2>오늘의 타임테이블</h2>${icon('clock')}</div><div class="schedule">${slots.length?slots.map(x=>`<button class="schedule-row ${s?.time===x.time&&s?.date===date?'active':''}" data-session="${x.time}"><span class="sched-time">${x.time}</span><strong>${x.type==='OPEN GYM'?'오픈짐':x.type}</strong><small>${date===today()&&minutes(x.end)<=seoulNow()?'종료':s?.time===x.time&&s?.date===date?(s.current?'진행 중':'선택'):x.type==='OPEN GYM'?'자유':'60분'}</small></button>`).join(''):'<div class="empty">오늘은 쉬어가는 날이에요.</div>'}</div><div class="schedule-foot">예약 없이 자유롭게 참여하세요.<span>평일 오픈짐 12:00–16:30 · 토요일 10:00–20:00</span></div></section><section class="panel attendance-card"><div class="small-label">꾸준함이 만드는 변화</div><h2 style="margin-top:6px">이번 달 나의 출석</h2><div class="att-number">${String(attend).padStart(2,'0')}<span>일 · 이번 달도 함께해요!</span></div><div class="progress"><div style="width:${Math.min(100,attend/20*100)}%"></div></div><div class="att-bottom"><span>한 번의 운동도 소중하게</span><button data-action="attendance-history">출석 달력 ↗</button></div></section></div></div><div class="lower-grid"><section class="panel"><div class="panel-head"><h2>함께 쌓는 오늘의 기록 <span class="tag">${p}</span></h2><button class="link" data-page="members">전체 보기 ${icon('arrow')}</button></div>${resultTable(p,3)}<div style="padding:9px 20px;font-size:9px;color:var(--muted)">예시 기록 포함 · 다른 조건의 결과는 통합 순위를 매기지 않아요.</div></section><section class="panel"><div class="panel-head"><h2>우리 박스 이야기</h2><button class="link" data-page="community">더 보기 ${icon('arrow')}</button></div><div class="board-preview">${state.posts.slice(0,2).map(post=>`<button data-post="${post.id}"><span class="tag ${post.category==='공동구매'?'green':''}">${post.category}</span><strong>${esc(post.title)}</strong><span class="board-meta">${esc(post.author)} · 댓글 ${post.comments.length}</span></button>`).join('')}</div></section></div>`}
function members(){return `${intro('함께 쌓는 기록', '같은 운동, 각자의 도전. 서로의 움직임을 응원해요.',datePicker())}<div class="page-toolbar"><div class="filter-tabs">${['WOD','B/T'].map(p=>`<button class="${recordsFilter===p?'active':''}" data-records-filter="${p}">${p}</button>`).join('')}</div><button class="btn primary" data-action="record">${icon('plus')}${coach?'회원 기록 입력':'내 기록 입력'}</button></div><div class="preview-note">예시 데이터가 포함되어 있어요. 실제 회원 간 공유는 아직 연결되지 않았습니다. 순위 참여를 꺼도 기록은 회원에게 공개되는 설정입니다.</div><section class="panel"><div class="panel-head"><h2>${dateLabel(date)} · ${recordsFilter}</h2>${unitToggle()}</div>${resultTable(recordsFilter)}</section><div class="panel calculator"><h3>조건이 같을 때만 공정하게</h3><p class="muted" style="font-size:12px;margin-bottom:0">중량·시간·횟수 등 기록 종류와 운동 조건이 같은 구간끼리 순위를 비교합니다. 현재 예시 인터벌 기록에는 등수를 표시하지 않습니다.</p></div>`}
const movements=['Front Squat','Back Squat','Deadlift','Clean & Jerk','Snatch','Strict Press'];
function best(m){const rs=state.rms.filter(r=>r.movement===m);return rs.sort((a,b)=>b.lbs-a.lbs)[0]}
function rm(){return `${intro('나의 가장 강한 순간', '한 번의 도전, 하나의 새로운 기준. 동작별 1RM을 모아보세요.',`<button class="btn primary" data-action="rm-add">${icon('plus')}1RM 기록</button>`)}<div class="page-toolbar"><span class="small-label">PERSONAL RECORDS · ${state.rms.length}개의 도전</span>${unitToggle()}</div><div class="content-grid">${movements.map(m=>{const b=best(m);return `<section class="panel rm-card"><div class="rm-icon">${icon('weight')}</div><button class="icon-btn add-rm" data-rm="${m}" aria-label="${m} 기록 추가">${icon('plus')}</button><h3>${m}</h3><div class="rm-number">${b?formatWeight(b.lbs):'—'}<small>${state.unit}</small></div><div class="rm-date">${b?`${esc(b.date)} · 나의 최고 기록`:'첫 번째 기록을 남겨보세요.'}</div><div class="rm-bottom"><span class="tag">${b?'PERSONAL BEST':'YOUR NEXT CHALLENGE'}</span><button class="link" data-rm-history="${m}">기록 이력 ↗</button></div></section>`}).join('')}</div><section class="panel calculator"><div class="panel-head" style="padding:0 0 17px"><h2>나의 1RM으로 중량 계산</h2>${icon('weight')}</div><label class="field" style="margin-top:18px">기준 동작<select id="calc-movement">${movements.map(m=>`<option>${m}</option>`).join('')}</select></label><div id="calc-results"></div></section>`}
function calc(){let m=$('#calc-movement')?.value;if(!m)return;const b=best(m);$('#calc-results').innerHTML=b?`<div class="calculator-results">${[50,60,70,75,80,90].map(p=>`<div>${p}%<strong>${formatWeight(b.lbs*p/100)}</strong>${state.unit}</div>`).join('')}</div><p class="field-hint" style="margin:15px 0 0">환산값입니다. 실제 원판 구성에 맞춰 중량을 조정해주세요.</p>`:'<div class="empty">이 동작의 1RM을 먼저 등록해주세요.</div>'}
function attendanceCalendar(){const first=today().slice(0,7)+'-01',days=new Date(+first.slice(0,4),+first.slice(5,7),0).getDate(),offset=new Date(first+'T12:00:00+09:00').getUTCDay();return `<div class="calendar">${['일','월','화','수','목','금','토'].map(d=>`<span class="weekday">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{let d=first.slice(0,8)+String(i+1).padStart(2,'0');return `<span class="${state.attendance.includes(d)?'attended':''} ${d===today()?'today':''}">${i+1}${state.attendance.includes(d)?' ✓':''}</span>`}).join('')}</div>`}
function myRecords(){return `${intro('어제보다 한 걸음 더', '꾸준히 쌓아온 나의 운동을 돌아보세요.')}<div class="stats-strip"><div class="panel stat-box"><span class="small-label">이번 달 출석</span><strong>${state.attendance.filter(d=>d.startsWith(today().slice(0,7))).length}<small>일</small></strong></div><div class="panel stat-box"><span class="small-label">나의 운동 기록</span><strong>${state.records.filter(r=>r.name===state.name).length}<small>개</small></strong></div><div class="panel stat-box"><span class="small-label">1RM 도전</span><strong>${state.rms.length}<small>회</small></strong></div></div><div class="page-toolbar"><div class="filter-tabs">${['운동 기록','출석 달력'].map(t=>`<button class="${myTab===t?'active':''}" data-mytab="${t}">${t}</button>`).join('')}</div>${myTab==='운동 기록'?`<button class="btn primary" data-action="record">${icon('plus')}기록 입력</button>`:''}</div><section class="panel settings-section">${myTab==='출석 달력'?`<h2>${today().slice(0,7).replace('-','년 ')}월</h2>${attendanceCalendar()}<p class="field-hint">체험 출석만 표시됩니다. GPS 출석은 체육관 위치 설정 후 사용할 수 있어요.</p>`:state.records.filter(r=>r.name===state.name).length?state.records.filter(r=>r.name===state.name).slice().reverse().map(r=>`<div class="history-row"><div>${esc(r.program)} · ${r.section}<small>${r.date} · ${esc(r.kind)}</small></div><div><strong>${resultValue(r)}</strong> <button class="link" data-edit-record="${r.id}">수정</button></div></div>`).join(''):'<div class="empty">아직 기록이 없어요.<br>첫 운동 기록을 남겨보세요.</div>'}</section>`}
function community(){const posts=state.posts.filter(p=>boardFilter==='전체'||p.category===boardFilter);return `${intro('우리 박스 이야기','운동도, 일상도 함께. 온오프 회원들의 소통 공간입니다.',`<button class="btn primary" data-action="new-post">${icon('edit')}글쓰기</button>`)}<div class="page-toolbar"><div class="filter-tabs">${['전체','운동 번개','공동구매','자유글'].map(t=>`<button class="${boardFilter===t?'active':''}" data-board-filter="${t}">${t}</button>`).join('')}</div><span class="small-label">${posts.length}개의 이야기</span></div><div class="board-list">${posts.map(p=>`<button class="panel post-card" data-post="${p.id}"><span class="tag ${p.category==='공동구매'?'green':''}">${p.category}</span><h3>${esc(p.title)}</h3><p>${esc(p.body.split('\n')[0])}</p><div class="post-footer"><span>${esc(p.author)} · ${p.date}</span><span>${p.category!=='자유글'?`참여 ${p.joined.length} · `:''}댓글 ${p.comments.length} ${icon('arrow')}</span></div></button>`).join('')||'<div class="panel empty">새로운 이야기를 시작해보세요.</div>'}</div>`}
function settings(){let theme=localStorage.getItem('onoff-theme')||'system';return `${intro('나에게 맞는 온오프','프로필과 운동 환경을 설정해보세요.')}<div class="settings-grid"><section class="panel settings-section"><h2>회원 정보</h2><div class="setting-row"><div><strong>${esc(state.name)}</strong><p>미리보기 회원 · 실제 계정 연결 전</p></div><button class="btn" data-action="name">이름 수정</button></div><div class="setting-row"><div><strong>카카오 계정</strong><p>카카오 개발자 설정 후 연결할 수 있어요.</p></div><button class="btn kakao" data-action="kakao">연결 안내</button></div><div class="setting-row"><div><strong>순위 참여</strong><p>끄면 내 기록은 공개되지만 순위에서는 제외돼요.</p></div><button class="switch ${state.rank?'on':''}" role="switch" aria-checked="${state.rank}" aria-label="순위 참여" data-action="rank"></button></div></section><section class="panel settings-section"><h2>화면과 단위</h2><div class="setting-row"><div><strong>화면 모드</strong><p>선택한 설정을 이 기기에 기억해요.</p></div><select id="theme-select" aria-label="화면 모드">${[['system','기기 설정'],['light','라이트'],['dark','다크']].map(([v,t])=>`<option value="${v}" ${v===theme?'selected':''}>${t}</option>`).join('')}</select></div><div class="setting-row"><div><strong>기본 중량 단위</strong><p>단위를 바꿔도 같은 무게로 환산해요.</p></div>${unitToggle()}</div><div class="setting-row"><div><strong>개인정보와 미리보기</strong><p>현재 데이터는 이 브라우저에만 저장돼요.</p></div><button class="link" data-action="preview-info">자세히 ↗</button></div></section></div>`}
function admin(){if(!coach)return settings();return `${intro('코치의 관리 공간','수업부터 회원까지, 오늘의 박스를 준비하세요.')}<div class="admin-banner">코치 화면 체험 중입니다. 권한 변경·승인은 이 브라우저의 예시 데이터에만 적용됩니다.</div><div class="stats-strip"><div class="panel stat-box"><span class="small-label">가입 승인 대기 · 예시</span><strong>${state.members.filter(m=>m.status==='pending').length}<small>명</small></strong></div><div class="panel stat-box"><span class="small-label">등록한 수업</span><strong>${Object.keys(state.workouts).length}<small>개</small></strong></div><div class="panel stat-box"><span class="small-label">입력된 기록</span><strong>${state.records.length}<small>개</small></strong></div></div><div class="settings-grid"><section class="panel settings-section"><h2>수업 관리</h2><p class="field-hint" style="margin-top:12px">날짜와 운동 구간별 기록 항목을 설정하세요.</p>${datePicker()}<div class="admin-actions" style="margin-top:18px"><button class="btn primary" data-edit-workout="WOD">WOD 등록·수정</button><button class="btn soft" data-edit-workout="B/T">B/T 등록·수정</button><button class="btn" data-action="record">회원 기록 입력</button></div></section><section class="panel settings-section"><h2>공지 배너 관리</h2><div class="setting-row"><div><strong>메인 공지 노출</strong><p>문구가 좌우로 흐르는 배너입니다.</p></div><button class="switch ${state.noticeOn?'on':''}" role="switch" aria-checked="${state.noticeOn}" aria-label="공지 배너 노출" data-action="notice-toggle"></button></div><button class="btn" data-action="edit-notice">공지 문구 수정</button></section><section class="panel settings-section"><h2>회원 승인</h2>${state.members.length?state.members.map(m=>`<div class="setting-row"><div><strong>${esc(m.name)}</strong><p>${m.status==='pending'?'가입 승인 대기':'승인 완료'} · 예시 회원</p></div>${m.status==='pending'?`<button class="btn primary" data-approve="${m.id}">승인</button>`:'<span class="tag green">승인됨</span>'}</div>`).join(''):'<div class="empty">대기 중인 회원이 없어요.</div>'}</section><section class="panel settings-section"><h2>실서비스 연결 상태</h2><div class="setting-row"><div><strong>카카오 로그인·회원 권한</strong><p>개발자 앱 설정 및 서버 연결 필요</p></div><span class="mini-badge">연결 전</span></div><div class="setting-row"><div><strong>GPS 출석</strong><p>체육관 좌표·허용 반경 설정 필요</p></div><span class="mini-badge">설정 전</span></div><div class="setting-row"><div><strong>회원 간 데이터 공유</strong><p>공용 데이터베이스 연결 필요</p></div><span class="mini-badge">연결 전</span></div></section></div>`}
function render(){if(!['home','members','records','rm','community','settings','admin'].includes(page))page='home';nav();$('#main').innerHTML=({home,members,records:myRecords,rm,community,settings,admin}[page])();if(page==='rm')calc();themeIcon();}
function go(p){page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'instant'})}
function modal(title,content){$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="close" aria-label="닫기">×</button></div><div class="modal-content">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close()}
function themeIcon(){$('#theme-button').innerHTML=icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}
function setTheme(t){localStorage.setItem('onoff-theme',t);document.documentElement.dataset.theme=t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t;themeIcon()}
function rmForm(m='Front Squat'){modal('나의 1RM 기록',`<form id="rm-form"><label class="field">운동 동작<select name="movement">${movements.map(x=>`<option ${x===m?'selected':''}>${x}</option>`).join('')}</select></label><div class="field-row"><label class="field">성공 중량<input name="weight" type="number" min="0.1" max="3000" step="0.1" required placeholder="예: 185"></label><label class="field">단위<select name="unit"><option ${state.unit==='lbs'?'selected':''}>lbs</option><option ${state.unit==='kg'?'selected':''}>kg</option></select></label></div><label class="field">측정 날짜<input type="date" name="date" value="${date}" max="${today()}" required></label><p class="field-hint">실제 성공한 1회 최대 중량을 기록해주세요.</p><div class="form-footer"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary">기록 저장</button></div></form>`)}
function recordForm(id){const existing=state.records.find(r=>r.id===id);let p=existing?.program||(page==='members'?recordsFilter:program)||'WOD';let d=existing?.date||(page==='home'?selected()?.date:date)||date;const w=workout(p,d);const secs=w.sections.map((s,i)=>({...s,index:i})).filter(s=>s.record);modal(coach?'회원 운동 기록 입력':'나의 운동 기록',`<form id="record-form" data-edit-id="${id||''}"><p class="field-hint">${d} · ${p} · 이 브라우저의 미리보기에 저장됩니다.</p>${coach?`<label class="field">회원 이름<input name="member" value="${esc(existing?.name||state.name)}" required maxlength="20"></label>`:''}<div class="field-row"><label class="field">운동 종류<select name="program" id="record-program"><option ${p==='WOD'?'selected':''}>WOD</option><option ${p==='B/T'?'selected':''}>B/T</option></select></label><label class="field">기록 구간<select name="section" id="record-section">${secs.map(s=>`<option value="${s.index}" ${existing?.section==='S'+(s.index+1)?'selected':''}>S${s.index+1} · ${esc(s.kind)}</option>`).join('')}</select></label></div><div id="record-fields"></div><label class="field">운동 날짜<input name="date" type="date" required value="${d}" max="${today()}"></label><label class="field">메모 (선택)<input name="note" maxlength="150" placeholder="사용한 중량, 변경 동작 등" value="${esc(existing?.note||'')}"></label><div class="form-footer"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary" ${secs.length?'':'disabled'}>기록 저장</button></div></form>`);recordFields(existing)}
function recordFields(existing){const f=$('#record-form');if(!f)return;const p=f.elements.program.value;const w=workout(p,f.elements.date.value||date);const sec=w.sections[+f.elements.section.value];const isWeight=sec&&['중량','1RM'].includes(sec.kind);$('#record-fields').innerHTML=!sec?'<p>이 수업은 기록을 받지 않아요.</p>':isWeight?`<div class="field-row"><label class="field">${sec.kind==='1RM'?'1RM 성공 중량':'사용 중량'}<input name="weight" type="number" min="0.1" max="3000" step="0.1" required value="${existing?.lbs?formatWeight(existing.lbs):''}" placeholder="예: 135"></label><label class="field">단위<select name="unit"><option ${state.unit==='lbs'?'selected':''}>lbs</option><option ${state.unit==='kg'?'selected':''}>kg</option></select></label></div>${sec.kind==='1RM'?'<p class="field-hint">본인 기록은 내 1RM 탭에도 자동으로 연결돼요.</p>':''}`:`<label class="field">${esc(sec.kind)}<input name="value" required maxlength="120" placeholder="${sec.kind==='시간'?'예: 09:35':sec.kind==='세트별 횟수·칼로리'?'예: 12 / 21 / 10 / 19 / 8 / 18':'결과를 입력하세요'}" value="${esc(existing?.value||'')}"></label>${sec.kind==='세트별 횟수·칼로리'?'<p class="field-hint">1·3·5세트: 스내치 횟수 / 2·4·6세트: 로우 칼로리</p>':''}`;}
function postModal(id){const p=state.posts.find(x=>x.id===id);if(!p)return;modal(esc(p.category),`<h2 style="font-size:21px;line-height:1.6">${esc(p.title)}</h2><div class="board-meta">${esc(p.author)} · ${p.date}</div><div class="post-body">${esc(p.body)}</div>${p.category!=='자유글'?`<button class="btn ${p.joined.includes(state.name)?'soft':'primary'} full" data-join="${id}">${icon('check')}${p.joined.includes(state.name)?'참여 취소':'참여하기'} · ${p.joined.length}명</button><p class="field-hint">${p.joined.length?'참여자: '+p.joined.map(esc).join(', '):'함께할 첫 번째 회원이 되어보세요.'}</p>`:''}<h3 style="margin-top:25px">댓글 ${p.comments.length}</h3>${p.comments.map(c=>`<div class="comment"><small>${esc(c.author)}</small>${esc(c.text)}</div>`).join('')}<form id="comment-form" data-post-id="${id}"><label class="field">댓글 남기기<input name="text" maxlength="300" placeholder="따뜻한 한마디를 남겨주세요." required></label><button class="btn primary">댓글 등록</button></form>${p.author===state.name||coach?`<button class="link" data-delete-post="${id}" style="margin-top:22px;color:#cb5762">글 삭제</button>`:''}`)}
function workoutForm(p){if(!coach)return;const w=workout(p);modal(`${p} 수업 등록 · ${date}`,`<form id="workout-form" data-program="${p}"><p class="field-hint">수업 내용을 작성하고 구간마다 필요한 기록을 선택하세요.</p>${w.sections.map((s,i)=>`<h3 style="margin-top:20px">S${i+1}</h3><label class="field">구간 제목<input name="title${i}" value="${esc(s.title)}" required maxlength="100"></label><label class="field">운동 내용<textarea name="text${i}" required maxlength="3000">${esc(s.text)}</textarea></label><label class="checkbox-label"><input type="checkbox" name="record${i}" ${s.record?'checked':''}>이 구간 기록 받기</label><label class="field">기록 종류<select name="kind${i}">${['중량','1RM','시간','횟수','라운드 + 횟수','칼로리','세트별 횟수·칼로리','완료 여부'].map(t=>`<option ${s.kind===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">1RM 동작 (1RM 선택 시 적용)<select name="movement${i}">${movements.map(m=>`<option ${m===(s.movement||'Front Squat')?'selected':''}>${m}</option>`).join('')}</select></label>`).join('')}<div class="form-footer"><button class="btn primary">수업 저장</button></div></form>`)}
function showInfo(){modal('첫 버전 미리보기 안내','<p>온오프의 디자인과 사용 흐름을 확인하는 첫 버전입니다.</p><p><strong>지금 체험할 수 있는 기능</strong><br>현재 시간에 맞춘 수업, 단위 변환, 운동 기록, 1RM·중량 계산, 커뮤니티, 코치의 수업·공지 관리입니다.</p><p><strong>아직 연결되지 않은 기능</strong><br>카카오 로그인·실제 회원 승인, 서버 저장·회원 간 공유, GPS 출석입니다. 카카오 개발자 앱과 체육관 위치 설정이 필요합니다.</p><p>입력한 데이터는 현재 브라우저에만 저장됩니다. 예시 회원·게시글이 포함되어 있으며, 실제 운영 전용 앱으로 사용하기 전 서버와 접근 권한을 연결해야 합니다.</p><button class="btn primary full" data-action="close">확인했어요</button>')}
const actions={close,settings:()=>go('settings'),theme:()=>{const dark=document.documentElement.dataset.theme==='dark';setTheme(dark?'light':'dark');if(page==='settings')render();toast(dark?'라이트 모드로 전환했어요.':'다크 모드로 전환했어요.')},coach:()=>{coach=!coach;go(coach?'admin':'home');toast(coach?'코치 화면 미리보기입니다.':'회원 화면으로 돌아왔어요.')},today:()=>{date=today();program=null;chosenSession=null;render()},'prev-date':()=>shiftDate(-1),'next-date':()=>shiftDate(1),record:()=>recordForm(),'rm-add':()=>rmForm(),rank:()=>{state.rank=!state.rank;state.records.filter(r=>r.name===state.name).forEach(r=>r.rank=state.rank);save();render();toast(state.rank?'순위 참여를 켰어요.':'순위 참여를 껐어요. 기록은 계속 공개돼요.')},notice:()=>{modal('ONOFF 공지사항',`<div class="post-body">${esc(state.notice)}</div><button class="btn primary full" data-action="close">확인</button>`)},'notice-toggle':()=>{if(!coach)return;state.noticeOn=!state.noticeOn;save();render()},'edit-notice':()=>{if(!coach)return;modal('공지 배너 문구',`<form id="notice-form"><label class="field">공지 내용<textarea name="notice" required maxlength="500">${esc(state.notice)}</textarea></label><button class="btn primary full">저장</button></form>`)},name:()=>modal('회원 이름 수정',`<form id="name-form"><label class="field">실명<input name="name" value="${esc(state.name)}" required maxlength="20" minlength="2"></label><button class="btn primary full">저장</button></form>`),kakao:()=>modal('카카오로 간편하게 시작',`<p>실서비스에서는 카카오 로그인 후 실명만 입력하면 가입을 신청할 수 있어요. 관리자 승인 후 체육관 앱을 이용합니다.</p><p class="field-hint">현재 카카오 개발자 앱이 연결되지 않아 실제 로그인·가입은 진행되지 않습니다.</p><button class="btn kakao full" disabled>카카오 로그인 · 연결 준비 중</button><button class="btn full" data-action="signup-preview">가입 신청 화면 체험</button>`),'signup-preview':()=>modal('회원 가입 신청 · 체험',`<form id="signup-form"><label class="field">체육관에서 사용하는 실명<input name="name" required minlength="2" maxlength="20" placeholder="이름을 입력해주세요"></label><p class="field-hint">실제 개인정보 수집 없이 화면 흐름을 확인하는 예시입니다. 승인된 회원에게 이름과 운동 기록이 공개되는 구조입니다.</p><label class="checkbox-label"><input type="checkbox" required>미리보기 가입 신청임을 확인했습니다.</label><button class="btn primary full">승인 신청 체험</button></form>`),'attendance-history':()=>{myTab='출석 달력';go('records')},attendance:()=>{if(state.attendance.includes(today()))return toast('오늘 출석을 이미 남겼어요.');modal('체육관 출석하기',`<p>체육관 도착 후 버튼을 누르면 현재 위치를 확인해 출석하는 방식입니다.</p><p><strong>체육관 위치가 아직 설정되지 않았어요.</strong><br>정확한 위치와 허용 반경을 설정한 후 GPS 출석을 사용할 수 있습니다.</p><p class="field-hint">현재는 위치 권한을 요청하지 않습니다. 아래 버튼은 이 브라우저에 체험 출석만 남깁니다.</p><button class="btn primary full" data-action="demo-attend">미리보기 출석 체험</button>`)},'demo-attend':()=>{if(!state.attendance.includes(today()))state.attendance.push(today());save();close();render();toast('체험 출석을 남겼어요. 실제 GPS 출석이 아닙니다.')},'new-post':()=>modal('우리 박스에 이야기 남기기',`<form id="post-form"><label class="field">말머리<select name="category"><option>운동 번개</option><option>공동구매</option><option>자유글</option></select></label><label class="field">제목<input name="title" required maxlength="80" placeholder="어떤 이야기를 나눌까요?"></label><label class="field">내용<textarea name="body" required maxlength="3000" placeholder="일시, 장소, 참여 방법 등을 적어주세요."></textarea></label><p class="field-hint">미리보기 글은 이 브라우저에만 저장됩니다.</p><button class="btn primary full">게시글 등록</button></form>`),'preview-info':showInfo};
function shiftDate(n){const d=new Date(date+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()+n);date=d.toISOString().slice(0,10);program=null;chosenSession=null;render()}
document.addEventListener('click',e=>{let el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.page)return go(d.page);if(d.action)return actions[d.action]?.();if(d.unit){state.unit=d.unit;save();return render()}if(d.program){program=d.program;return render()}if(d.session){const s=schedule(date).find(s=>s.time===d.session);chosenSession={...s,date,current:date===today()&&minutes(s.time)<=seoulNow()&&minutes(s.end)>seoulNow()};program=s.type==='B/T'?'B/T':'WOD';return render()}if(d.recordsFilter){recordsFilter=d.recordsFilter;return render()}if(d.boardFilter){boardFilter=d.boardFilter;return render()}if(d.mytab){myTab=d.mytab;return render()}if(d.rm)return rmForm(d.rm);if(d.editRecord)return recordForm(d.editRecord);if(d.rmHistory){const rs=state.rms.filter(r=>r.movement===d.rmHistory).sort((a,b)=>b.date.localeCompare(a.date));return modal(esc(d.rmHistory)+' · 기록 이력',rs.length?rs.map(r=>`<div class="history-row"><span>${r.date}</span><strong>${formatWeight(r.lbs)} ${state.unit}</strong></div>`).join(''):'<div class="empty">아직 기록이 없어요.</div>')}if(d.post)return postModal(d.post);if(d.join){const p=state.posts.find(p=>p.id===d.join);p.joined=p.joined.includes(state.name)?p.joined.filter(n=>n!==state.name):[...p.joined,state.name];save();render();return postModal(p.id)}if(d.deletePost){const p=state.posts.find(p=>p.id===d.deletePost);if(!p||(!coach&&p.author!==state.name))return;modal('게시글 삭제',`<p>이 게시글과 댓글을 삭제할까요?</p><div class="form-footer"><button class="btn" data-post="${p.id}">돌아가기</button><button class="btn primary" data-confirm-delete="${p.id}">삭제하기</button></div>`);return}if(d.confirmDelete){state.posts=state.posts.filter(p=>p.id!==d.confirmDelete);save();close();render();return toast('게시글을 삭제했어요.')}if(d.editWorkout)return workoutForm(d.editWorkout);if(d.approve&&coach){const m=state.members.find(m=>m.id===d.approve);m.status='approved';save();render();toast(`${m.name}님의 체험 승인을 완료했어요.`)}});
document.addEventListener('change',e=>{if(e.target.id==='date-input'){date=e.target.value||today();program=null;chosenSession=null;render()}if(e.target.id==='theme-select')setTheme(e.target.value);if(e.target.id==='calc-movement')calc();if(e.target.id==='record-program'){const f=$('#record-form'),w=workout(f.elements.program.value,f.elements.date.value||date);$('#record-section').innerHTML=w.sections.map((s,i)=>s.record?`<option value="${i}">S${i+1} · ${esc(s.kind)}</option>`:'').join('');recordFields()}if(e.target.id==='record-section')recordFields();});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));const id=crypto.randomUUID();if(f.id==='rm-form'){state.rms.push({id,movement:data.movement,lbs:+data.weight*(data.unit==='kg'?2.2046226218:1),date:data.date});save();close();render();return toast('새로운 도전을 1RM에 기록했어요.')}if(f.id==='record-form'){const w=workout(data.program,data.date),s=w.sections[+data.section];if(!s?.record)return toast('이 구간은 기록을 받지 않아요.');const old=state.records.find(r=>r.id===f.dataset.editId);if(old&&!coach&&old.name!==state.name)return;const r={id:old?.id||id,name:coach?data.member.trim():state.name,date:data.date,program:data.program,section:'S'+(+data.section+1),kind:s.kind,rank:state.rank,note:data.note,writer:coach?'coach':'member'};if(data.weight)r.lbs=+data.weight*(data.unit==='kg'?2.2046226218:1);else r.value=data.value;if(!r.name||(!r.lbs&&!r.value?.trim()))return toast('기록 내용을 입력해주세요.');if(old)state.records[state.records.indexOf(old)]=r;else state.records.push(r);state.rms=state.rms.filter(x=>x.source!==r.id);if(s.kind==='1RM'&&r.name===state.name&&r.lbs)state.rms.push({id,source:r.id,movement:s.movement||'Front Squat',lbs:r.lbs,date:r.date});save();close();render();return toast('운동 기록을 저장했어요.')}if(f.id==='post-form'){if(!data.title.trim()||!data.body.trim())return;state.posts.unshift({id,category:data.category,title:data.title.trim(),body:data.body.trim(),author:state.name,date:today(),joined:[],comments:[]});save();close();render();return toast('새 이야기를 등록했어요.')}if(f.id==='comment-form'){if(!data.text.trim())return;const p=state.posts.find(p=>p.id===f.dataset.postId);p.comments.push({author:state.name,text:data.text.trim()});save();return postModal(p.id)}if(f.id==='name-form'){const old=state.name;if(!data.name.trim()||data.name.trim().length<2)return;state.name=data.name.trim();state.records.filter(r=>r.name===old).forEach(r=>r.name=state.name);state.posts.forEach(p=>{if(p.author===old)p.author=state.name;p.comments.forEach(c=>{if(c.author===old)c.author=state.name});p.joined=p.joined.map(n=>n===old?state.name:n)});save();close();render();return toast('이름을 변경했어요.')}if(f.id==='notice-form'&&coach){if(!data.notice.trim())return;state.notice=data.notice.trim();save();close();render();return toast('공지 문구를 저장했어요.')}if(f.id==='signup-form'){state.members.push({id,name:data.name.trim(),status:'pending'});save();modal('가입 신청 완료 · 체험','<p>관리자가 회원 확인 후 승인하는 단계입니다.</p><p class="field-hint">실제 가입은 진행되지 않았어요. 코치 화면에서 체험 신청을 확인할 수 있습니다.</p><button class="btn primary full" data-action="close">확인</button>');return}if(f.id==='workout-form'&&coach){const w={title:f.dataset.program==='WOD'?'Work of the Day':'Body Training',sections:[0,1].map(i=>({title:data['title'+i],text:data['text'+i],record:data['record'+i]==='on',kind:data['kind'+i],movement:data['movement'+i]}))};state.workouts[date+'_'+f.dataset.program]=w;save();close();render();toast('수업을 저장했어요. 해당 날짜에서 확인할 수 있어요.')}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p!==page){page=p;render()}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if((localStorage.getItem('onoff-theme')||'system')==='system'){setTheme('system');}});
function tick(){$('#live-clock').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date())+' KST'}
render();tick();let lastMinute=seoulNow();setInterval(()=>{tick();const m=seoulNow();if(m!==lastMinute){lastMinute=m;if(page==='home'&&!chosenSession&&!$('#modal').open)render()}},15000);
